  1	/* ============================================================
  2	   views/orchestrator.js — Orchestrator View
  3	   MCP Server Dashboard SPA — Phase 5 (WP-011)
  4	
  5	   Renders the top-level orchestrator view:
  6	     Section A: plan path input + preflight + start
  7	     Section B: live run queue table with polling
  8	     Footer: CLI reference card
  9	
 10	   Depends on: API (api-client.js), Router (router.js),
 11	               OrchestratorWidgets (js/orchestrator-widgets.js),
 12	               escapeHtml (utils.js)
 13	   ============================================================ */
 14	
 15	// Module-scoped log-preview cleanup registry.
 16	// Each renderOrchestrator() call drains this array before creating new widgets.
 17	var _orchLogPreviewCleanups = [];
 18	
 19	/**
 20	 * Top-level orchestrator view entry point.
 21	 * Called by Router.dispatch() when the user navigates to #/orchestrator.
 22	 *
 23	 * @param {HTMLElement} app - The root #app container element.
 24	 */
 25	function renderOrchestrator(app) {
 26	  // 1. Drain log preview cleanup callbacks from the previous render.
 27	  _orchLogPreviewCleanups.forEach(function (fn) { try { fn(); } catch (_) {} });
 28	  _orchLogPreviewCleanups = [];
 29	
 30	  // 2. Render the static skeleton.
 31	  app.innerHTML =
 32	    '<h1 class="section-title">Orchestrator</h1>' +
 33	
 34	    '<section class="orch-section">' +
 35	      '<h2 class="orch-section-title">Start New Run</h2>' +
 36	      '<div class="orch-start-panel">' +
 37	        '<div class="orch-plan-input-row">' +
 38	          '<input type="text" id="orch-plan-path" class="orch-plan-input"' +
 39	            ' placeholder="Absolute path to plan.md…" autocomplete="off">' +
 40	          '<button type="button" id="orch-preflight-btn" class="btn btn-secondary">' +
 41	            'Run Preflight' +
 42	          '</button>' +
 43	          '<button type="button" id="orch-start-btn" class="btn btn-primary" disabled>' +
 44	            'Start Run' +
 45	          '</button>' +
 46	        '</div>' +
 47	        '<div id="orch-preflight-results"></div>' +
 48	      '</div>' +
 49	    '</section>' +
 50	
 51	    '<section class="orch-section">' +
 52	      '<h2 class="orch-section-title">Run Queue</h2>' +
 53	      '<div id="orch-queue-container"><p class="text-muted">Loading queue…</p></div>' +
 54	    '</section>' +
 55	
 56	    '<section class="orch-section orch-cli-section">' +
 57	      OrchestratorWidgets.renderCliReference() +
 58	    '</section>';
 59	
 60	  // 3. Bind UI references.
 61	  var preflightBtn = document.getElementById('orch-preflight-btn');
 62	  var startBtn     = document.getElementById('orch-start-btn');
 63	  var planInput    = document.getElementById('orch-plan-path');
 64	  var resultsEl    = document.getElementById('orch-preflight-results');
 65	
 66	  var allChecksPassed = false;
 67	
 68	  // 4. Render preflight results checklist.
 69	  function renderPreflightResults(checks) {
 70	    if (!checks || !checks.length) {
 71	      resultsEl.innerHTML = '';
 72	      allChecksPassed = false;
 73	      startBtn.disabled = true;
 74	      return;
 75	    }
 76	    allChecksPassed = checks.every(function (c) { return c.pass; });
 77	    startBtn.disabled = !allChecksPassed;
 78	    if (!startBtn.disabled) startBtn.textContent = 'Start Run';
 79	
 80	    var html = '<ul class="preflight-list">';
 81	    checks.forEach(function (c) {
 82	      var cls = c.pass ? 'preflight-pass' : 'preflight-fail';
 83	      html += '<li class="preflight-check ' + cls + '">';
 84	      html += '<span class="preflight-icon">' + (c.pass ? '✓' : '✗') + '</span>';
 85	      html += ' <strong>' + escapeHtml(c.name) + '</strong>: ' + escapeHtml(c.detail);
 86	      if (!c.pass && c.fix) {
 87	        html += ' <span class="preflight-fix">Fix: <code>' + escapeHtml(c.fix) + '</code></span>';
 88	      }
 89	      html += '</li>';
 90	    });
 91	    html += '</ul>';
 92	    resultsEl.innerHTML = html;
 93	  }
 94	
 95	  // 5. Preflight button handler.
 96	  preflightBtn.addEventListener('click', function () {
 97	    var planPath = planInput.value.trim();
 98	    if (!planPath) { window.alert('Please enter a plan path.'); return; }
 99	
100	    preflightBtn.disabled = true;

101	    preflightBtn.textContent = 'Running…';
102	    resultsEl.innerHTML = '<p class="text-muted">Running preflight checks…</p>';
103	    allChecksPassed = false;
104	    startBtn.disabled = true;
105	
106	    API.orchestratorStart(planPath, true).then(function (result) {
107	      renderPreflightResults((result && result.checks) ? result.checks : []);
108	    }).catch(function (err) {
109	      resultsEl.innerHTML = '<p class="error-banner">Preflight error: ' +
110	        escapeHtml((err && err.message) ? err.message : String(err)) + '</p>';
111	    }).then(function () {
112	      preflightBtn.disabled = false;
113	      preflightBtn.textContent = 'Run Preflight';
114	    });
115	  });
116	
117	  // 6. Start Run button handler.
118	  startBtn.addEventListener('click', function () {
119	    var planPath = planInput.value.trim();
120	    if (!planPath || !allChecksPassed) return;
121	
122	    startBtn.disabled = true;
123	    startBtn.textContent = 'Starting…';
124	
125	    API.orchestratorStart(planPath, false).then(function (result) {
126	      if (result && result.started) {
127	        var runStatusFilename = result.runStatusFilename || null;
128	        planInput.value = '';
129	        resultsEl.innerHTML =
130	          '<p class="success-banner">✓ Orchestrator launched' +
131	          (result.pid ? ' (PID\u00a0' + result.pid + ')' : '') +
132	          '. Waiting for the run to appear in the queue below…</p>';
133	        allChecksPassed = false;
134	        startBtn.disabled = true;
135	        refreshQueue();
136	
137	        // Poll the run-status tombstone so we can surface fatal early
138	        // failures (e.g. invalid API key) that complete before the first
139	        // queue poll cycle.
140	        if (runStatusFilename) {
141	          var pollCount = 0;
142	          var MAX_STATUS_POLLS = 15; // 2s × 15 = 30s window
143	          var statusPollTimer = setInterval(function () {
144	            pollCount++;
145	            API.orchestratorGetRunStatus(runStatusFilename).then(function (status) {
146	              if (!status) return; // file not yet written — run still in progress
147	              clearInterval(statusPollTimer);
148	              if (status.result === 'ERROR' && status.error) {
149	                resultsEl.innerHTML =
150	                  '<p class="error-banner">Run failed: ' +
151	                  escapeHtml(status.error) + '</p>';
152	              }
153	              // SUCCESS: queue will reflect the project; leave the banner.
154	            }).catch(function () {
155	              // Transient error — keep polling.
156	            });
157	            if (pollCount >= MAX_STATUS_POLLS) {
158	              clearInterval(statusPollTimer);
159	            }
160	          }, 2000);
161	          _orchLogPreviewCleanups.push(function () { clearInterval(statusPollTimer); });
162	        }
163	      } else {
164	        // Checks re-evaluated by server — update the checklist.
165	        renderPreflightResults((result && result.checks) ? result.checks : []);
166	      }
167	    }).catch(function (err) {
168	      window.alert('Failed to start: ' + ((err && err.message) ? err.message : String(err)));
169	      startBtn.disabled = !allChecksPassed;
170	      startBtn.textContent = 'Start Run';
171	    }).then(function () {
172	      startBtn.textContent = 'Start Run';
173	    });
174	  });
175	
176	  // 7. Queue refresh and rendering — tracks expanded row IDs across refreshes.
177	  var expandedIds = {};
178	
179	  function refreshQueue() {
180	    // Stop log preview intervals started in the previous queue render.
181	    _orchLogPreviewCleanups.forEach(function (fn) { try { fn(); } catch (_) {} });
182	    _orchLogPreviewCleanups = [];
183	
184	    var container = document.getElementById('orch-queue-container');
185	    if (!container) return;
186	
187	    API.orchestratorGetQueue().then(function (entries) {
188	      renderQueueTable(container, Array.isArray(entries) ? entries : []);
189	    }).catch(function () {
190	      // Best-effort polling — keep existing content on transient errors.
191	    });
192	  }
193	
194	  // ---- renderQueueTable helpers (closure-scoped) ----------------------------
195	
196	  /** Removes the success banner from the preflight results area, if present.
197	   *  Error banners are intentionally left intact.
198	   *
199	   *  Closure dependency: `resultsEl` — the #orch-preflight-results element
200	   *  captured by renderOrchestrator() at line 64. */
201	  function _clearSuccessBanner() {
202	    var successBanner = resultsEl.querySelector('.success-banner');
203	    if (successBanner) {
204	      successBanner.remove();
205	    }
206	  }
207	
208	  /** Builds the queue table HTML string from the entries array.
209	   *  Returns the complete <table>…</table> markup ready to be assigned to
210	   *  container.innerHTML. */
211	  function _buildQueueHtml(entries) {
212	    var html = '<table class="table orch-queue-table"><thead>' +
213	      '<tr><th></th><th>Plan</th><th>Status</th><th>Elapsed</th><th>Progress</th><th>Actions</th></tr>' +
214	      '</thead><tbody>';
215	    entries.forEach(function (entry) {
216	      var id         = entry.id || '';
217	      var status     = entry.effectiveStatus || 'pending';
218	      var planName   = _orchBasename(entry.planPath || '');
219	      var elapsed    = _orchElapsed(entry.startedAt);
220	      var isExpanded = !!expandedIds[id];
221	      var statusBadgeHtml = '<span class="badge badge-' + escapeHtml(status) + '">' +
222	        escapeHtml(_orchStatusLabel(status)) + '</span>';
223	      // Progress cell: badge + text summary + optional log link.
224	      var progressHtml = OrchestratorWidgets.renderProgressBadge(entry.lastAction || null);
225	      if (entry.progress) {
226	        progressHtml += ' <span class="orch-progress-text">' + escapeHtml(entry.progress) + '</span>';
227	      }
228	      if (entry.logFilename && entry.expectedSlug) {
229	        progressHtml += ' <a href="#/projects/' +
230	          encodeURIComponent(entry.expectedSlug) + '/runs/' +
231	          encodeURIComponent(entry.logFilename) + '" class="orch-log-link">View Log →</a>';
232	      } else if (!entry.progress) {
233	        progressHtml += ' <span class="text-muted">Waiting for log…</span>';
234	      }
235	      html += '<tr class="orch-queue-row orch-row-' + escapeHtml(status) + '"' +
236	        ' data-entry-id="' + escapeHtml(id) + '">';
237	      html += '<td class="orch-toggle-cell">' +
238	        '<button type="button" class="orch-row-toggle btn-icon" data-entry-id="' + escapeHtml(id) + '">' +
239	        (isExpanded ? '▼' : '▶') + '</button></td>';
240	      html += '<td class="orch-plan-cell" title="' + escapeHtml(entry.planPath || '') + '">' +
241	        escapeHtml(planName) + '</td>';
242	      html += '<td class="orch-status-cell">' + statusBadgeHtml + '</td>';
243	      html += '<td class="orch-elapsed-cell">' + escapeHtml(elapsed) + '</td>';
244	      html += '<td class="orch-progress-cell">' + progressHtml + '</td>';
245	      html += '<td class="orch-actions-cell" data-actions-for="' + escapeHtml(id) + '"></td>';
246	      html += '</tr>';
247	      if (isExpanded) {
248	        html += '<tr class="orch-log-row" data-entry-id="' + escapeHtml(id) + '">' +
249	          '<td colspan="6">' +
250	          '<div class="orch-log-preview" id="orch-log-' + escapeHtml(id) + '"></div>' +
251	          '</td></tr>';
252	      }
253	    });
254	    html += '</tbody></table>';
255	    return html;
256	  }
257	
258	  /** Injects DOM-based action buttons and toggle listeners into the rendered
259	   *  table. Must be called after container.innerHTML has been set.
260	   *
261	   *  Branch priority (dismissibility-first):
262	   *    1. pending  → Kill button   (process is still running)
263	   *    2. dead     → Dismiss button (process has exited without completing)
264	   *    3. projectExists → View Project link (project ledger is on disk)
265	   *  The dead branch precedes the projectExists branch so that a dead entry
266	   *  that also has a known project slug always renders Dismiss, not View Project.
267	   *
268	   *  Closure dependencies (from renderOrchestrator() scope):
269	   *    `expandedIds`            — tracks which queue rows are expanded; mutated
270	   *                               by toggle clicks to persist state across refreshes.
271	   *    `refreshQueue`           — triggers a fresh API fetch + re-render after
272	   *                               a Kill/Dismiss action or toggle click. */
273	  function _bindQueueActions(container, entries) {
274	    entries.forEach(function (entry) {
275	      var id     = entry.id || '';
276	      var status = entry.effectiveStatus || 'pending';
277	      var cell   = container.querySelector('[data-actions-for="' + id + '"]');
278	      if (!cell) return;
279	
280	      if (status === 'pending') {
281	        cell.appendChild(OrchestratorWidgets.renderKillButton(id, function () {
282	          delete expandedIds[id];
283	          refreshQueue();
284	        }));
285	      } else if (status === 'dead') {
286	        cell.appendChild(OrchestratorWidgets.renderDismissButton(id, function () {
287	          delete expandedIds[id];
288	          refreshQueue();
289	        }));
290	      } else if (entry.projectExists === true && entry.expectedSlug) {
291	        var link = document.createElement('a');
292	        link.href = '#/projects/' + encodeURIComponent(entry.expectedSlug);
293	        link.className = 'btn btn-sm btn-secondary orch-project-link';
294	        link.textContent = 'View Project';
295	        cell.appendChild(link);
296	      }
297	    });
298	
299	    var toggleBtns = container.querySelectorAll('.orch-row-toggle');
300	    Array.prototype.forEach.call(toggleBtns, function (btn) {

301	      btn.addEventListener('click', function () {
302	        var id = btn.getAttribute('data-entry-id');
303	        if (id) expandedIds[id] = !expandedIds[id];
304	        refreshQueue();
305	      });
306	    });
307	  }
308	
309	  /** Starts log previews for all currently expanded rows and registers their
310	   *  cleanup callbacks in _orchLogPreviewCleanups.
311	   *
312	   *  Closure dependencies (from renderOrchestrator() scope):
313	   *    `expandedIds`              — read to determine which rows are currently
314	   *                                 expanded; only those rows get a live preview.
315	   *    `_orchLogPreviewCleanups`  — the module-level cleanup registry; each
316	   *                                 preview's cleanup callback is pushed here so
317	   *                                 it is cancelled when renderOrchestrator() or
318	   *                                 refreshQueue() next runs. */
319	  function _mountLogPreviews(container, entries) {
320	    entries.forEach(function (entry) {
321	      var id = entry.id || '';
322	      if (!expandedIds[id] || !entry.logFilename || !entry.expectedSlug) return;
323	      var previewEl = document.getElementById('orch-log-' + id);
324	      if (!previewEl) return;
325	      var cleanup = OrchestratorWidgets.renderLogPreview(
326	        previewEl,
327	        entry.expectedSlug,
328	        entry.logFilename,
329	      );
330	      _orchLogPreviewCleanups.push(cleanup);
331	    });
332	  }
333	
334	  // ---- renderQueueTable coordinator ----------------------------------------
335	
336	  function renderQueueTable(container, entries) {
337	    // Save viewport scroll position before replacing innerHTML — the document
338	    // viewport is the scrolling context (not the container, which has no
339	    // overflow CSS), so window.scrollY is the correct save/restore target.
340	    var savedScrollY = window.scrollY;
341	
342	    if (!entries.length) {
343	      container.innerHTML = '<p class="text-muted orch-empty-queue">No active runs in the queue.</p>';
344	      return;
345	    }
346	
347	    _clearSuccessBanner();
348	    container.innerHTML = _buildQueueHtml(entries);
349	    _bindQueueActions(container, entries);
350	    _mountLogPreviews(container, entries);
351	
352	    // Restore scroll position after all DOM manipulation is complete.
353	    // Must be the last statement so intermediate DOM mutations do not
354	    // interfere with the restored position.
355	    window.scrollTo(0, savedScrollY);
356	  }
357	
358	  // 8. Kick off the first queue fetch and register the polling interval.
359	  refreshQueue();
360	  Router._setPolling(refreshQueue, 5000);
361	}
362	
363	// ---------------------------------------------------------------------------
364	// Private helpers
365	// ---------------------------------------------------------------------------
366	
367	/** Returns the final path segment (filename or folder name). */
368	function _orchBasename(path) {
369	  var parts = String(path).replace(/\\/g, '/').split('/');
370	  return parts[parts.length - 1] || path;
371	}
372	
373	/** Human-readable label for an effectiveStatus value. */
374	function _orchStatusLabel(status) {
375	  if (status === 'started') return 'Started';
376	  if (status === 'dead')    return 'Dead';
377	  return 'Pending';
378	}
379	
380	/** Formats elapsed time from an ISO start timestamp. */
381	function _orchElapsed(startedAt) {
382	  if (!startedAt) return '—';
383	  try {
384	    var diff = Date.now() - new Date(startedAt).getTime();
385	    if (isNaN(diff) || diff < 0) return '—';
386	    var secs = Math.round(diff / 1000);
387	    if (secs < 60)  return secs + 's';
388	    var mins = Math.floor(secs / 60);
389	    if (mins < 60)  return mins + 'm ' + (secs % 60) + 's';
390	    return Math.floor(mins / 60) + 'h ' + (mins % 60) + 'm';
391	  } catch (_) {
392	    return '—';
393	  }
394	}

  1	// @vitest-environment jsdom
  2	
  3	/**
  4	 * Tests for gui/public/views/orchestrator.js
  5	 *
  6	 * All acceptance criteria tested:
  7	 *   AC-1: "Run Preflight" calls API.orchestratorStart(planPath, true) and
  8	 *         renders a pass/fail checklist.
  9	 *   AC-2: "Start Run" button disabled initially; enabled only when all
 10	 *         preflight checks pass; calls API.orchestratorStart(planPath, false).
 11	 *   AC-3: Queue table fetches on render and registers 5-second polling via
 12	 *         Router._setPolling. Each entry renders status badge, elapsed time,
 13	 *         and progress.
 14	 *   AC-4: Pending entries show kill button; started entries show project link;
 15	 *         dead entries show dismiss button.
 16	 *   AC-5: Expanding a row starts a log preview via
 17	 *         OrchestratorWidgets.renderLogPreview(); re-render calls its cleanup.
 18	 *   AC-6: CLI reference card HTML is present at the bottom of the view.
 19	 *   AC-7: All log preview cleanup functions are invoked when renderOrchestrator
 20	 *         is called a second time (re-render scenario).
 21	 *
 22	 * Uses jsdom + vm.runInThisContext to load the browser-side script.
 23	 * API, Router, OrchestratorWidgets, and escapeHtml are set on globalThis.
 24	 */
 25	
 26	import { describe, it, expect, beforeAll, beforeEach, afterEach, vi, type Mock } from 'vitest';
 27	import { readFileSync } from 'node:fs';
 28	import { join } from 'node:path';
 29	import vm from 'node:vm';
 30	import type { QueueEntry } from '../../src/gui/queue/types.js';
 31	
 32	// ---------------------------------------------------------------------------
 33	// Load scripts
 34	// ---------------------------------------------------------------------------
 35	
 36	const publicDir = join(__dirname, '../../gui/public');
 37	
 38	const utilsJs        = readFileSync(join(publicDir, 'utils.js'), 'utf-8');
 39	const orchestratorJs = readFileSync(join(publicDir, 'views/orchestrator.js'), 'utf-8');
 40	
 41	// ---------------------------------------------------------------------------
 42	// Global type stubs
 43	// ---------------------------------------------------------------------------
 44	
 45	declare global {
 46	  // eslint-disable-next-line no-var
 47	  var renderOrchestrator: (app: HTMLElement) => void;
 48	  // eslint-disable-next-line no-var
 49	  var API: {
 50	    orchestratorStart:    Mock;
 51	    orchestratorGetQueue: Mock;
 52	    orchestratorKill:     Mock;
 53	    orchestratorDismiss:  Mock;
 54	  };
 55	  // eslint-disable-next-line no-var
 56	  var Router: {
 57	    _setPolling: Mock;
 58	    _clearPolling: Mock;
 59	  };
 60	  // eslint-disable-next-line no-var
 61	  var OrchestratorWidgets: {
 62	    renderCliReference:  Mock;
 63	    renderKillButton:    Mock;
 64	    renderDismissButton: Mock;
 65	    renderLogPreview:    Mock;
 66	    renderProgressBadge: Mock;
 67	    renderStatusCard:    Mock;
 68	  };
 69	}
 70	
 71	// ---------------------------------------------------------------------------
 72	// Setup: install globals, load scripts once
 73	// ---------------------------------------------------------------------------
 74	
 75	beforeAll(() => {
 76	  // Install utils.js globals (escapeHtml, etc.)
